-- RobotShop shipping database and worldwide location seed.
-- Source: GeoNames cities15000 + countryInfo; CC BY 4.0, https://www.geonames.org/
-- Import with psql; COPY data is embedded below. No network downloads required.
-- Safe to rerun: migrations are checksummed and the seed is versioned.
\set ON_ERROR_STOP on
BEGIN;
SELECT pg_advisory_xact_lock(74103106);
CREATE TABLE IF NOT EXISTS public.shipping_migrations (
  version integer PRIMARY KEY, checksum text NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now()
);
DO $migration$
BEGIN
  IF EXISTS (SELECT FROM public.shipping_migrations WHERE version = 1) THEN
    IF NOT EXISTS (SELECT FROM public.shipping_migrations WHERE version = 1 AND checksum = 'b95187ba76777ce963e4efef4a81fe7b56f5379d632e83c0971e3b7e73121e27') THEN
      RAISE EXCEPTION 'Shipping migration 1 checksum mismatch';
    END IF;
  ELSE
CREATE SCHEMA IF NOT EXISTS shipping;
CREATE TABLE shipping.metadata (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE shipping.countries (code varchar(2) PRIMARY KEY, name text NOT NULL);
CREATE TABLE shipping.cities (
  id integer PRIMARY KEY,
  country_code varchar(2) NOT NULL REFERENCES shipping.countries(code),
  name text NOT NULL,
  search_name text COLLATE "C" NOT NULL,
  region text NOT NULL,
  latitude double precision NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude double precision NOT NULL CHECK (longitude BETWEEN -180 AND 180)
);
CREATE INDEX city_search ON shipping.cities(country_code, search_name, id);

  END IF;
END
$migration$;
DO $migration$
BEGIN
  IF EXISTS (SELECT FROM public.shipping_migrations WHERE version = 2) THEN
    IF NOT EXISTS (SELECT FROM public.shipping_migrations WHERE version = 2 AND checksum = '620f55478a65165130941dd47e36eb37b27f8ffeb99e184c90385b92cde944f2') THEN
      RAISE EXCEPTION 'Shipping migration 2 checksum mismatch';
    END IF;
  ELSE
CREATE TABLE shipping.shipment_requests (
    order_id uuid PRIMARY KEY,
    event_id uuid NOT NULL UNIQUE,
    payload jsonb NOT NULL,
    status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested')),
    received_at timestamptz NOT NULL DEFAULT now()
);

  END IF;
END
$migration$;
CREATE TEMP TABLE seed_countries (LIKE shipping.countries) ON COMMIT DROP;
CREATE TEMP TABLE seed_cities (LIKE shipping.cities) ON COMMIT DROP;
DO $seed$
BEGIN
IF NOT EXISTS (SELECT FROM shipping.metadata WHERE key = 'seed' AND value = '940c5126a17b54bad0b133ca131c528ee3b583a0ce7ce0476942e9c991aae127') THEN
DELETE FROM shipping.cities;
DELETE FROM shipping.countries;
ON CONFLICT (key) DO UPDATE SET value = excluded.value;
END IF;
END
$seed$;
DO $permissions$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'shipping_app') THEN
    GRANT USAGE ON SCHEMA shipping TO shipping_app;
    GRANT SELECT ON shipping.metadata, shipping.countries, shipping.cities TO shipping_app;
    GRANT INSERT ON shipping.shipment_requests TO shipping_app;
  END IF;
END
$permissions$;
COMMIT;
SELECT (SELECT count(*) FROM shipping.countries) AS countries,
       (SELECT count(*) FROM shipping.cities) AS cities;
